#!/usr/bin/env python3
"""Prove final encoder output identical to the fully externally verified regional fonts."""
import argparse,hashlib,json
from pathlib import Path
from variants import invoke
from glyf import load_reference
ROOT=Path(__file__).resolve().parents[2]
def main():
 p=argparse.ArgumentParser();p.add_argument('--binary',type=Path,required=True);p.add_argument('--work',type=Path,required=True);p.add_argument('--report',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();ref=load_reference(ROOT.parent);family=ref.family_of('prop','Large');names=ref.names(family,'Square','test');path=lambda s:a.work/(s+'.bdf')
 common=['variants','--base',path('SC'),'--lang',f'zh-Hant,zh-HK={path("TC")}','--lang',f'ja={path("JP")}','--lang',f'ko={path("KR")}','--script',f'latn,grek,cyrl={path("Latin")}','--family',family,'--vendor','TONG','--font-version','test','--copyright',names['copyright'],'--license',names['licenseDescription'],'--license-url',names['licenseInfoURL']];results=[]
 for case in json.loads(a.report.read_text())['results']:
  if 'glyphs' not in case:continue
  _,shape,kind=case['case'].split('-');out=a.work/('final-reproduced-'+shape+'.'+kind);invoke(a.binary,*common,'--shape',shape,'-o',out);actual=hashlib.sha256(out.read_bytes()).hexdigest();assert actual==case['sha256'],(case['case'],actual,case['sha256']);results.append({'case':case['case'],'sha256':actual,'bytes_exact':True})
 a.output.write_text(json.dumps({'binary_sha256':hashlib.sha256(a.binary.read_bytes()).hexdigest(),'reason':'The only post-matrix encoder change sets maxContext=0 for fonts without GSUB; full regional fonts retain maxContext=1. All generated bytes are reproduced exactly.','results':results},indent=2)+'\n');print('FULL REGIONAL BYTES EXACT',len(results))
if __name__=='__main__':main()
